function isChecked(v) {
  if (typeof v === 'boolean') return v;
  if (typeof v === 'string') return v.trim().toUpperCase() === 'TRUE';
  return false;
}
const out = [];
for (const item of $input.all()) {
  const j = item.json;
  const email = j['Email'];
  if (!email) continue;
  if (!isChecked(j['Salesforce'])) continue;
  if (isChecked(j['Contacted'])) continue;
  if (isChecked(j['Playbook'])) continue;
  if (j['Meeting']) continue;
  const outreachCount = Number(j['Outreach Count'] || 0);
  if (outreachCount >= 3) continue;
  out.push({ json: j });
}
return out;

